-- Publish Weaver Intelligence Ops
-- Seed AI Governance search query definitions and RSS sources.
-- Target: PostgreSQL
-- Notes:
--   1. Query date filtering should be generated by the application from date_window_days.
--   2. RSS feed URLs should be validated by the ingestion job before enabling production polling.
--   3. This script is idempotent and safe to re-run.

CREATE SCHEMA IF NOT EXISTS ops;

CREATE TABLE IF NOT EXISTS ops.rss_sources
(
    id text COLLATE pg_catalog."default" NOT NULL,
    name text COLLATE pg_catalog."default" NOT NULL,
    description text COLLATE pg_catalog."default" NOT NULL DEFAULT ''::text,
    homepage_url text COLLATE pg_catalog."default" NOT NULL,
    feed_url text COLLATE pg_catalog."default",
    source_category text COLLATE pg_catalog."default" NOT NULL DEFAULT 'industry'::text,
    include_terms text[] COLLATE pg_catalog."default" NOT NULL DEFAULT '{}'::text[],
    exclude_terms text[] COLLATE pg_catalog."default" NOT NULL DEFAULT '{}'::text[],
    governance_themes text[] COLLATE pg_catalog."default" NOT NULL DEFAULT '{}'::text[],
    date_window_days integer NOT NULL DEFAULT 30,
    top_x integer NOT NULL DEFAULT 10,
    minimum_score integer NOT NULL DEFAULT 60,
    frequency text COLLATE pg_catalog."default" NOT NULL DEFAULT 'daily'::text,
    status text COLLATE pg_catalog."default" NOT NULL DEFAULT 'enabled'::text,
    created_at timestamp with time zone NOT NULL DEFAULT now(),
    updated_at timestamp with time zone NOT NULL DEFAULT now(),
    last_polled_at timestamp with time zone,
    next_poll_at timestamp with time zone,
    last_success_at timestamp with time zone,
    last_failure_at timestamp with time zone,
    failure_count integer NOT NULL DEFAULT 0,
    last_error text COLLATE pg_catalog."default",
    CONSTRAINT rss_sources_pkey PRIMARY KEY (id),
    CONSTRAINT rss_sources_homepage_url_check CHECK (homepage_url ~* '^https?://'),
    CONSTRAINT rss_sources_feed_url_check CHECK (feed_url IS NULL OR feed_url ~* '^https?://'),
    CONSTRAINT rss_sources_date_window_days_check CHECK (date_window_days >= 1 AND date_window_days <= 365),
    CONSTRAINT rss_sources_top_x_check CHECK (top_x >= 1 AND top_x <= 100),
    CONSTRAINT rss_sources_minimum_score_check CHECK (minimum_score >= 0 AND minimum_score <= 100),
    CONSTRAINT rss_sources_frequency_check CHECK (frequency = ANY (ARRAY['manual'::text, 'hourly'::text, 'daily'::text, 'weekly'::text])),
    CONSTRAINT rss_sources_status_check CHECK (status = ANY (ARRAY['enabled'::text, 'paused'::text])),
    CONSTRAINT rss_sources_source_category_check CHECK (source_category = ANY (ARRAY[
        'regulatory'::text,
        'standards'::text,
        'enterprise'::text,
        'ai_lab'::text,
        'academic'::text,
        'news'::text,
        'industry'::text,
        'vendor'::text
    ]))
);

CREATE INDEX IF NOT EXISTS idx_rss_sources_status_frequency
    ON ops.rss_sources (status, frequency);

CREATE INDEX IF NOT EXISTS idx_rss_sources_governance_themes
    ON ops.rss_sources USING gin (governance_themes);

DROP TRIGGER IF EXISTS update_rss_sources_updated_at ON ops.rss_sources;
CREATE TRIGGER update_rss_sources_updated_at
    BEFORE UPDATE ON ops.rss_sources
    FOR EACH ROW EXECUTE FUNCTION ops.update_updated_at_column();

CREATE INDEX IF NOT EXISTS idx_query_definitions_status_frequency
    ON ops.query_definitions (status, frequency);

CREATE INDEX IF NOT EXISTS idx_query_definitions_governance_themes
    ON ops.query_definitions USING gin (governance_themes);

